@php($moduleRoutePrefix=$moduleRoutePrefix??'wms')
<div class="container-fluid px-3 px-lg-4 py-4"><div class="d-flex justify-content-between align-items-end mb-4"><div><p class="eyebrow mb-2">PURCHASING / PROCUREMENT</p><h1 class="h3 mb-2">ใบสั่งซื้อ (Purchase Order)</h1><p class="text-secondary mb-0">สร้างและติดตามคำสั่งซื้อก่อนรับสินค้า</p></div>@if(auth()->user()->hasPermission('wms.purchase-orders.create'))<a class="btn btn-dark" href="{{route($moduleRoutePrefix.'.purchase-orders.create')}}"><i class="bx bx-plus me-1"></i>สร้าง PO</a>@endif</div>
<div class="card border-0 shadow-sm"><div class="card-body"><div class="table-responsive"><table id="purchase-orders-table" class="table table-hover align-middle w-100" data-url="{{route($moduleRoutePrefix.'.purchase-orders.data')}}"><thead><tr><th>เลขที่</th><th>วันที่</th><th>Supplier</th><th>อ้างอิง PR</th><th>วันที่คาดรับ</th><th class="text-end">ยอดรวม</th><th>สถานะ</th><th class="text-end">จัดการ</th></tr></thead></table></div></div></div></div>
